mapper.select:
SELECT message.id AS message_id, message.conversation_id, message.client_message_id, message.sender_id, CASE WHEN message.sender_role = 'SYSTEM' THEN '系统' ELSE sender.display_name END AS sender_display_name, message.sender_role, CASE message.sender_role WHEN 'RESIDENT' THEN '居民' WHEN 'METER_READER' THEN '抄表员' WHEN 'ADMIN' THEN '管理员' WHEN 'SYSTEM' THEN '系统' END AS sender_role_name, message.message_type, CASE message.message_type WHEN 'TEXT' THEN '文本消息' WHEN 'SYSTEM' THEN '系统消息' END AS message_type_name, CASE WHEN message.deleted = 1 THEN '[消息已删除]' ELSE message.content END AS content, message.deleted, message.created_at FROM chat_message AS message LEFT JOIN sys_user AS sender ON sender.id = message.sender_id WHERE message.conversation_id = #{conversationId}
AND message.id < #{beforeMessageId}
ORDER BY message.id DESC LIMIT #{limit}
